package main
import "fmt"

func main(){
  ch1, err1 := StartOperation(1)
  ch2, err2 := StartOperation(2)
  select {
  case p := <-ch1:
    fmt.Println("op1:", p)
  case e := <-err1:
    fmt.Println("op1 err:", e)
  }
  select {
  case p := <-ch2:
    fmt.Println("op2:", p)
  case e := <-err2:
    fmt.Println("op2 err:", e)
  }
}
```

